import discord
from discord import app_commands
from discord.ext import commands
import aiohttp
import json
import os

# --- ANSI 顏色定義 ---
class ANSI:
    RESET = "\u001b[0m"
    BLUE = "\u001b[34m"
    CYAN = "\u001b[36m"
    YELLOW = "\u001b[33m"
    WHITE = "\u001b[37m"
    PURPLE = "\u001b[35m"
    GRAY = "\u001b[30;1m"

def format_line(label, value, color=ANSI.CYAN):
    """格式化對齊行：針對中文字元長度微調對齊"""
    # 使用全形冒號或手動補位確保整齊
    return f"{ANSI.WHITE}{label:<8} : {color}{value}{ANSI.RESET}"

# --- 互動按鈕類別 ---
class MapleView(discord.ui.View):
    def __init__(self, ocid, api_key, base_url, original_data):
        super().__init__(timeout=180)
        self.ocid = ocid
        self.api_key = api_key
        self.base_url = base_url
        self.original_data = original_data
        self.headers = {"accept": "application/json", "x-nxopen-api-key": self.api_key}

    async def get_data(self, endpoint):
        async with aiohttp.ClientSession() as session:
            url = f"{self.base_url}/{endpoint}?ocid={self.ocid}"
            async with session.get(url, headers=self.headers) as resp:
                return await resp.json() if resp.status == 200 else None

    def create_basic_embed(self, data):
        embed = discord.Embed(title=f"🌸 {data.get('character_name')}", color=discord.Color.orange())
        if data.get("character_image"):
            embed.set_thumbnail(url=data.get("character_image"))
            
        content = "```ansi\n"
        content += f"{ANSI.GRAY}基本資訊{ANSI.RESET}\n"
        content += format_line("伺服器", data.get("world_name")) + "\n"
        content += format_line("公會", data.get("character_guild_name") or "無") + "\n"
        content += format_line("職業", data.get("character_class")) + "\n"
        # 加上經驗值百分比顯示
        exp_rate = data.get('character_exp_rate', '0')
        content += format_line("等級", f"{data.get('character_level')} ({exp_rate}%)") + "\n"
        content += "```"
        
        embed.description = content
        return embed
    
    @discord.ui.button(label="返回基本資訊", style=discord.ButtonStyle.gray, emoji="⬅️")
    async def back_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        embed = self.create_basic_embed(self.original_data)
        await interaction.response.edit_message(embed=embed, view=self)

    @discord.ui.button(label="機體詳細資訊", style=discord.ButtonStyle.danger, emoji="📊")
    async def stat_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        
        # 同時請求三種資料
        stat_data = await self.get_data("character/stat")
        symbol_data = await self.get_data("character/symbol-equipment")
        hexa_data = await self.get_data("character/hexamatrix")
        
        if not stat_data: 
            return await interaction.followup.send("❌ 無法讀取 API 資料，請檢查 API Key 或角色名稱。", ephemeral=True)

        stats = {item['stat_name']: item['stat_value'] for item in stat_data.get("final_stat", [])}
        
        # 1. 機體資訊處理
        stat_ansi = "```ansi\n"
        stat_ansi += f"{ANSI.GRAY}機體資訊{ANSI.RESET}\n"
        stat_ansi += format_line("戰鬥力", "{:,}".format(int(stats.get("戰鬥力", 0))), ANSI.YELLOW) + "\n"
        stat_ansi += format_line("屬性攻擊", "{:,}".format(int(stats.get("最高屬性攻擊力", 0)))) + "\n"
        stat_ansi += format_line("總傷害 ", f"{stats.get('傷害')}%") + "\n"
        stat_ansi += format_line("BOSS傷害", f"{stats.get('BOSS怪物傷害')}%") + "\n"
        stat_ansi += format_line("爆擊傷害", f"{stats.get('爆擊傷害')}%") + "\n"
        stat_ansi += format_line("最終傷害", f"{stats.get('最終傷害')}%") + "\n"
        stat_ansi += format_line("無視防禦", f"{stats.get('無視防禦率')}%") + "\n"
        stat_ansi += "```"

        # 2. 六轉核心處理 (增加屬性核心解析)
        total_spent = 0
        TOTAL_MAX_FRAGS = 35862
        hexa_ansi = "```ansi\n"
        hexa_ansi += f"{ANSI.PURPLE}🟣 六轉核心{ANSI.RESET}\n"
        
        if hexa_data:
            core_groups = {"技能核心": [], "精通核心": [], "強化核心": [], "共用核心": []}
            for core in hexa_data.get("character_hexa_core_equipment", []):
                c_type = core.get("hexa_core_type")
                c_name = core.get("hexa_core_name")
                c_lv = str(core.get("hexa_core_level"))
                total_spent += get_hexa_spent(c_type, int(c_lv))
                if c_type in core_groups:
                    core_groups[c_type].append([c_name,c_lv])

            for label, items in core_groups.items():
                if items:
                    # items 是 [[名稱, 等級], [名稱, 等級]]
                    # 轉換成 "名稱(等級)" 的格式
                    formatted_list = [f"{item[0]}({item[1]})" for item in items]
                    val = " |\n".join(formatted_list)
                hexa_ansi += format_line(label, "\n"+val, ANSI.CYAN) + "\n"
        else:
            hexa_ansi += "未開啟六轉功能\n"
        
        hexa_ansi += "```"

        # 3. 符文處理
        symbol_ansi = "```ansi\n"
        symbol_ansi += f"{ANSI.GRAY}🔮 符文詳細等級{ANSI.RESET}\n"
        if symbol_data:
            symbols = symbol_data.get("symbol", [])
            arc_list = [str(s.get("symbol_level")) for s in symbols if "祕法符文" in s.get("symbol_name")]
            aut_list = [str(s.get("symbol_level")) for s in symbols if "真實符文" in s.get("symbol_name")]                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
            symbol_ansi += f"{ANSI.WHITE}ARC : {ANSI.BLUE}{' | '.join(arc_list) if arc_list else '無'}{ANSI.RESET}\n"
            symbol_ansi += f"{ANSI.WHITE}AUT : {ANSI.YELLOW}{' | '.join(aut_list) if aut_list else '無'}{ANSI.RESET}\n"
        symbol_ansi += "```"

        hexa_progress_percent = (total_spent / TOTAL_MAX_FRAGS) * 100 if TOTAL_MAX_FRAGS > 0 else 0

        embed = discord.Embed(title=f"📜 詳細報告：{self.original_data.get('character_name')}", color=discord.Color.dark_purple())
        embed.set_thumbnail(url=self.original_data.get('character_image'))
    
        embed.add_field(name="📊 機體能力", value=stat_ansi, inline=False)
        embed.add_field(name=f"🧬 六轉進度 [{hexa_progress_percent: .2f} %]", value=hexa_ansi, inline=False)
        embed.add_field(name=f"💠 符文資訊 [{stats.get('神秘力量')} | {stats.get('真實之力')}]", value=symbol_ansi, inline=False)
        embed.set_footer(text=f"查詢時間：{interaction.created_at.strftime('%Y-%m-%d %H:%M')}")

        await interaction.edit_original_response(embed=embed, view=self)
# --- 六轉碎片消耗累計表 (1-30級累計消耗量) ---
HEXA_COST_MAP = {
    "技能核心": [0, 100, 130, 165, 205, 250, 300, 355, 415, 480, 680, 760, 850, 950, 1060, 1180, 1310, 1450, 1600, 1760, 2110, 2280, 2460, 2650, 2850, 3060, 3280, 3510, 3750, 4000, 4500],
    "精通核心": [0, 50, 65, 83, 103, 126, 151, 179, 209, 242, 342, 382, 427, 477, 532, 592, 657, 727, 802, 882, 1057, 1142, 1232, 1327, 1427, 1532, 1642, 1757, 1877, 2002, 2252],
    "強化核心": [0, 75, 98, 125, 155, 189, 227, 269, 314, 363, 513, 573, 641, 716, 799, 889, 987, 1092, 1205, 1325, 1588, 1716, 1851, 1994, 2144, 2302, 2467, 2640, 2820, 3008, 3383],
    "共用核心": [0, 125, 163, 207, 257, 314, 377, 446, 521, 603, 853, 953, 1066, 1191, 1329, 1479, 1642, 1817, 2005, 2205, 2643, 2856, 3081, 3319, 3569, 3832, 4107, 4395, 4695, 5008, 5633, 6250]
}

def get_hexa_spent(c_type, level):
    """計算單一核心已花費碎片"""
    
    table = HEXA_COST_MAP.get(c_type)
    if table and 0 <= level < len(table):
        return table[level]
    return 0
# --- 主 Cog ---
class MapleCog(commands.Cog):
    def __init__(self, bot):
        self.bot = bot
        self.base_url = "https://open.api.nexon.com/maplestorytw/v1"
        self.config_path = "config.json" # 修正：定義 config_path

    def get_api_key(self):
        if os.path.exists(self.config_path):
            with open(self.config_path, 'r', encoding='utf-8') as f:
                config = json.load(f)
                return config.get("nexon_api_key")
        return None
    
    @app_commands.command(name="角色資訊", description="查詢新楓之谷角色基本資料與詳細機體")
    @app_commands.describe(角色名稱="請輸入要查詢的角色 ID")
    async def character_info(self, interaction: discord.Interaction, 角色名稱: str):
        api_key = self.get_api_key()
        if not api_key:
            return await interaction.response.send_message("❌ 機器人尚未設定 API Key。", ephemeral=True)
        
        await interaction.response.defer()
        headers = {"accept": "application/json", "x-nxopen-api-key": api_key}
        
        async with aiohttp.ClientSession() as session:
            # 1. 獲取 OCID
            async with session.get(f"{self.base_url}/id?character_name={角色名稱}", headers=headers) as resp:
                if resp.status != 200: 
                    return await interaction.followup.send(f"❌ 找不到角色「{角色名稱}」，請確認名稱是否正確。")
                ocid = (await resp.json()).get("ocid")
            
            # 2. 獲取基本資訊
            async with session.get(f"{self.base_url}/character/basic?ocid={ocid}", headers=headers) as resp:
                if resp.status != 200:
                    return await interaction.followup.send("❌ 無法取得角色基本資訊。")
                info = await resp.json()

        # 啟動 View
        view = MapleView(ocid, api_key, self.base_url, info)
        embed = view.create_basic_embed(info)
        await interaction.followup.send(embed=embed, view=view)

async def setup(bot):
    await bot.add_cog(MapleCog(bot))